from d1_apply import describe

A = "✏️s/🔌️plugins/🀄️wfc/🗿️artifacts"

describe(f"{A}/🖼️bitmap/🏅️standards/🔖️1/🪆️subsets/✳️any/✏️editor/🦀️.rs", "create_bitmap_editor", [
    ("set-input-pixels", "Overwrites a rectangle of the input sample at x, y with the given palette indices (base64, one byte per pixel, row by row); the solve learns its patterns from this sample.", "Überschreibt ein Rechteck des Eingabemusters an x, y mit den angegebenen Palettenindizes (Base64, ein Byte pro Pixel, zeilenweise); der Löser lernt seine Muster aus diesem Beispiel."),
    ("resize-input", "Resizes the input sample to the given width and height; growing pads the new right and bottom margin with palette colour 0, shrinking drops the pixels outside.", "Ändert die Größe des Eingabemusters; beim Vergrößern wird der neue rechte und untere Rand mit Palettenfarbe 0 gefüllt, beim Verkleinern fallen die Pixel außerhalb weg."),
    ("add-palette-color", "Inserts an RGBA colour into the palette at the given index and renumbers every pixel and pin that used that index or a higher one.", "Fügt der Palette an der angegebenen Position eine RGBA-Farbe hinzu und nummeriert alle Pixel und Anheftungen um, die diesen oder einen höheren Index verwenden."),
    ("change-palette-color", "Recolours one palette entry in place to the given RGBA value; every pixel and pin using that index changes colour with it.", "Färbt einen Paletteneintrag direkt auf den angegebenen RGBA-Wert um; alle Pixel und Anheftungen mit diesem Index ändern ihre Farbe mit."),
    ("remove-palette-color", "Removes one palette colour and renumbers the entries above it; refused while any pixel or pin still uses the colour.", "Entfernt eine Palettenfarbe und nummeriert die darüberliegenden Einträge um; wird abgelehnt, solange noch ein Pixel oder eine Anheftung die Farbe verwendet."),
    ("set-active-color", "Arms the palette colour the input window's brush paints with; only this window's brush state changes, not the document.", "Wählt die Palettenfarbe, mit der der Pinsel des Eingabefensters malt; nur der Pinselzustand dieses Fensters ändert sich, nicht das Dokument."),
    ("change-model", "Sets the overlapping model the solve learns from the sample: pattern size N, how many of the sample's 8 rotations and reflections to use, whether the sample wraps around, and an optional ground colour.", "Legt das überlappende Modell fest, das der Löser aus dem Muster lernt: Mustergröße N, wie viele der 8 Drehungen und Spiegelungen genutzt werden, ob das Muster umläuft, und eine optionale Bodenfarbe."),
    ("change-seed", "Sets the random seed the solve starts from; the same seed and model always produce the same output bitmap.", "Legt den Zufallsstartwert des Lösers fest; derselbe Startwert und dasselbe Modell erzeugen immer dieselbe Ausgabebitmap."),
    ("solve", "Starts the fill tool run that generates the output bitmap from the input sample; the result stays a preview until it is pinned, so the document does not change.", "Startet den Füll-Werkzeuglauf, der aus dem Eingabemuster die Ausgabebitmap erzeugt; das Ergebnis bleibt eine Vorschau, bis es angeheftet wird, das Dokument ändert sich nicht."),
    ("commit-fill-solve", "Hands a finished fill run's pixels and contradiction flag to the output window's preview; the document is not changed, Pin Solution keeps a result.", "Übergibt die Pixel und das Widerspruchskennzeichen eines fertigen Füll-Laufs an die Vorschau des Ausgabefensters; das Dokument ändert sich nicht, Lösung anheften behält ein Ergebnis."),
    ("resize-output", "Sets the width, height and wrap-around of the bitmap the solve generates; pins outside the new size are removed.", "Legt Breite, Höhe und Umlauf der Bitmap fest, die der Löser erzeugt; Anheftungen außerhalb der neuen Größe werden entfernt."),
    ("pin-pixel", "Fixes one output pixel at x, y to a palette colour before solving; the solve must keep it.", "Legt ein Ausgabepixel an x, y vor dem Lösen auf eine Palettenfarbe fest; der Löser muss sie beibehalten."),
    ("unpin-pixel", "Releases the pin on one output pixel at x, y so the solve chooses its colour again; refused when the pixel carries no pin.", "Löst die Anheftung eines Ausgabepixels an x, y, sodass der Löser dessen Farbe wieder selbst wählt; wird abgelehnt, wenn das Pixel nicht angeheftet ist."),
    ("setActiveExample", "Replaces the whole document (sample, palette, model, output size, seed and pins) with one of the plugin's bundled bitmap examples, by example id.", "Ersetzt das gesamte Dokument (Muster, Palette, Modell, Ausgabegröße, Startwert und Anheftungen) durch eines der mitgelieferten Bitmap-Beispiele, anhand der Beispiel-Id."),
    ("pin-solution", "Makes a finished solve durable by pinning every output pixel to the colour the solve chose, replacing any pin that disagrees; a contradiction is refused.", "Macht eine fertige Lösung dauerhaft, indem jedes Ausgabepixel auf die vom Löser gewählte Farbe angeheftet wird; abweichende Anheftungen werden ersetzt, ein Widerspruch wird abgelehnt."),
], [("stroke-begin", "Input"), ("stroke-extend", "Input"), ("stroke-commit", "Input")])

describe(f"{A}/🔲️grid2d/🏅️standards/🔖️1/🪆️subsets/✳️any/✏️editor/🦀️.rs", "create_grid2d_editor", [
    ("change-seed", "Sets the random seed the solve starts from; the same seed, tiles and rules always produce the same tiling.", "Legt den Zufallsstartwert des Lösers fest; derselbe Startwert mit denselben Kacheln und Regeln ergibt immer dieselbe Kachelung."),
    ("resize-grid", "Sets the grid to the given number of columns and rows; pins and masks on cells outside the new extent are removed.", "Setzt das Raster auf die angegebene Anzahl Spalten und Zeilen; Anheftungen und Ausblendungen außerhalb der neuen Ausdehnung werden entfernt."),
    ("change-cell-size", "Sets the world width and height of one grid cell, the box each tile's image is scaled into and the spacing the grid window snaps to.", "Legt Breite und Höhe einer Rasterzelle in Weltmaßen fest, das Feld, in das jedes Kachelbild skaliert wird, und den Abstand, an dem das Rasterfenster fängt."),
    ("change-periodicity", "Sets whether the grid wraps around horizontally and vertically, so tiles on one edge must fit the tiles on the opposite edge.", "Legt fest, ob das Raster horizontal und vertikal umläuft, sodass Kacheln am einen Rand zu denen am gegenüberliegenden Rand passen müssen."),
    ("create-tile", "Adds a new tile with the given id and sampling weight to the tile set the solve may place.", "Fügt dem Kachelsatz, den der Löser setzen darf, eine neue Kachel mit der angegebenen Id und Gewichtung hinzu."),
    ("delete-tile", "Removes a tile from the tile set together with every adjacency rule that names it and every cell pinned to it.", "Entfernt eine Kachel aus dem Kachelsatz samt aller Nachbarschaftsregeln, die sie nennen, und aller Zellen, die auf sie angeheftet sind."),
    ("change-tile-weight", "Sets how strongly the solve favours one tile when several fit; a higher weight makes it more frequent.", "Legt fest, wie stark der Löser eine Kachel bevorzugt, wenn mehrere passen; ein höheres Gewicht macht sie häufiger."),
    ("change-tile-media", "Replaces the image one tile is drawn with (media as JSON); its id, weight, rules and pins stay unchanged.", "Ersetzt das Bild, mit dem eine Kachel gezeichnet wird (Medium als JSON); Id, Gewicht, Regeln und Anheftungen bleiben unverändert."),
    ("create-rule", "Allows or forbids tile B next to tile A in one direction; pairs without a rule are forbidden, so the rules are the complete whitelist.", "Erlaubt oder verbietet Kachel B in einer Richtung neben Kachel A; Paare ohne Regel sind verboten, die Regeln bilden also die vollständige Positivliste."),
    ("delete-rule", "Removes one adjacency rule by id; the tile pair falls back to forbidden in that direction.", "Entfernt eine Nachbarschaftsregel anhand ihrer Id; das Kachelpaar gilt in dieser Richtung wieder als verboten."),
    ("pin-cell", "Fixes the cell at column x, row y to the given tile before solving; the solve must keep it.", "Legt die Zelle in Spalte x, Zeile y vor dem Lösen auf die angegebene Kachel fest; der Löser muss sie beibehalten."),
    ("unpin-cell", "Releases the pin on the cell at column x, row y so the solve chooses its tile again.", "Löst die Anheftung der Zelle in Spalte x, Zeile y, sodass der Löser deren Kachel wieder selbst wählt."),
    ("mask-cell", "Cuts the cell at column x, row y out of the problem: it gets no tile, and any pin it held is removed.", "Nimmt die Zelle in Spalte x, Zeile y aus dem Problem heraus: Sie erhält keine Kachel, eine vorhandene Anheftung wird entfernt."),
    ("unmask-cell", "Puts the masked cell at column x, row y back into the problem so the solve fills it again.", "Nimmt die ausgeblendete Zelle in Spalte x, Zeile y wieder ins Problem auf, sodass der Löser sie wieder füllt."),
    ("pick-cell", "Applies the grid window's armed utility to the cell at column x, row y: Pin fixes the armed tile there, Mask cuts the cell out, Select changes nothing.", "Wendet das gewählte Hilfsmittel des Rasterfensters auf die Zelle in Spalte x, Zeile y an: Anheften setzt dort die gewählte Kachel fest, Ausblenden nimmt die Zelle heraus, Auswählen ändert nichts."),
    ("set-active-tile", "Arms the tile the grid window's Pin utility places; only this window's state changes, not the document.", "Wählt die Kachel, die das Hilfsmittel Anheften im Rasterfenster setzt; nur der Zustand dieses Fensters ändert sich, nicht das Dokument."),
    ("set-grid-visible", "Shows or hides the cell grid lines in the grid window; a view setting that leaves the document unchanged.", "Blendet die Rasterlinien im Rasterfenster ein oder aus; eine Ansichtseinstellung, die das Dokument nicht ändert."),
    ("set-grid-snap-enabled", "Turns snapping to the grid on or off for pointer gestures in the grid window; the document is not changed.", "Schaltet das Fangen am Raster für Zeigergesten im Rasterfenster ein oder aus; das Dokument ändert sich nicht."),
    ("set-grid-factor", "Sets the spacing factor of the grid window's snap grid relative to the cell size; the document is not changed.", "Legt den Abstandsfaktor des Fangrasters im Rasterfenster relativ zur Zellgröße fest; das Dokument ändert sich nicht."),
    ("solve", "Starts the fill tool run that tiles the grid from its tiles, rules, pins and masks; the tiling is shown as a preview and does not change the document.", "Startet den Füll-Werkzeuglauf, der das Raster aus Kacheln, Regeln, Anheftungen und Ausblendungen kachelt; die Kachelung wird als Vorschau gezeigt und ändert das Dokument nicht."),
    ("commit-fill", "Keeps a finished fill run's tiling (as JSON) in the grid window so it stays visible; the document is not changed.", "Behält die Kachelung eines fertigen Füll-Laufs (als JSON) im Rasterfenster, damit sie sichtbar bleibt; das Dokument ändert sich nicht."),
    ("setActiveExample", "Replaces the whole document (grid, tiles, rules, pins and seed) with one of the plugin's bundled 2D grid examples, by example id.", "Ersetzt das gesamte Dokument (Raster, Kacheln, Regeln, Anheftungen und Startwert) durch eines der mitgelieferten 2D-Raster-Beispiele, anhand der Beispiel-Id."),
], [("set-camera", "Chrome")])

describe(f"{A}/🧱️grid3d/🏅️standards/🔖️1/🪆️subsets/✳️any/✏️editor/🦀️.rs", "create_grid3d_editor", [
    ("changeSeed", "Sets the random seed the 3D solve starts from; the same seed, tiles and rules always produce the same block arrangement.", "Legt den Zufallsstartwert des 3D-Lösers fest; derselbe Startwert mit denselben Kacheln und Regeln ergibt immer dieselbe Blockanordnung."),
    ("resizeGrid", "Sets the 3D grid to the given width, height and depth in cells; refused when a pinned or masked cell would fall outside the new extent.", "Setzt das 3D-Raster auf die angegebene Breite, Höhe und Tiefe in Zellen; wird abgelehnt, wenn eine angeheftete oder ausgeblendete Zelle außerhalb läge."),
    ("changeCellSizes", "Rewrites the per-cell sizes along one axis, which makes the 3D grid non-uniform; the list must have one size per cell of that axis.", "Schreibt die Zellgrößen entlang einer Achse neu und macht das 3D-Raster damit ungleichmäßig; die Liste braucht genau eine Größe pro Zelle dieser Achse."),
    ("changePeriodicity", "Sets whether the 3D grid wraps around along x, y and z, so blocks on one face must fit the blocks on the opposite face.", "Legt fest, ob das 3D-Raster entlang x, y und z umläuft, sodass Blöcke an einer Seite zu denen an der gegenüberliegenden Seite passen müssen."),
    ("createTile", "Adds a new block tile with the given id, label, weight and RGBA colour to the tile set the 3D solve may place.", "Fügt dem Kachelsatz des 3D-Lösers eine neue Blockkachel mit der angegebenen Id, Bezeichnung, Gewichtung und RGBA-Farbe hinzu."),
    ("deleteTile", "Removes a block tile together with every adjacency rule and every cell pin that names it.", "Entfernt eine Blockkachel samt aller Nachbarschaftsregeln und Zellanheftungen, die sie nennen."),
    ("changeTileWeight", "Sets how strongly the 3D solve favours one tile when several fit a cell; a higher weight makes it more frequent.", "Legt fest, wie stark der 3D-Löser eine Kachel bevorzugt, wenn mehrere in eine Zelle passen; ein höheres Gewicht macht sie häufiger."),
    ("changeTileColor", "Recolours one block tile to the given RGBA value, keeping its mesh if it has one; its id, weight and rules stay unchanged.", "Färbt eine Blockkachel auf den angegebenen RGBA-Wert um und behält ein vorhandenes Netz bei; Id, Gewicht und Regeln bleiben unverändert."),
    ("createRule", "Allows or forbids tile B on one of the six faces of tile A; pairs no rule mentions are forbidden, so the rules are a closed allow-list.", "Erlaubt oder verbietet Kachel B an einer der sechs Seiten von Kachel A; Paare ohne Regel sind verboten, die Regeln bilden also eine geschlossene Positivliste."),
    ("deleteRule", "Removes one adjacency rule by id; since unmentioned pairs are forbidden, deleting an allowing rule narrows what the solve may place.", "Entfernt eine Nachbarschaftsregel anhand ihrer Id; da nicht genannte Paare verboten sind, schränkt das Löschen einer erlaubenden Regel den Löser ein."),
    ("pinCell", "Fixes the cell at x, y, z to the given tile before solving; refused on a masked cell, and a pin already there is replaced.", "Legt die Zelle an x, y, z vor dem Lösen auf die angegebene Kachel fest; bei einer ausgeblendeten Zelle abgelehnt, eine vorhandene Anheftung wird ersetzt."),
    ("unpinCell", "Releases the pin on the cell at x, y, z so the 3D solve may place any tile there again.", "Löst die Anheftung der Zelle an x, y, z, sodass der 3D-Löser dort wieder jede Kachel setzen darf."),
    ("maskCell", "Carves the cell at x, y, z out of the grid so the 3D solve leaves it empty, which shapes non-box volumes; refused on a pinned cell.", "Nimmt die Zelle an x, y, z aus dem Raster, sodass der 3D-Löser sie leer lässt, womit sich Nicht-Quader-Formen bilden; bei einer angehefteten Zelle abgelehnt."),
    ("unmaskCell", "Puts the carved-out cell at x, y, z back into the grid so the 3D solve fills it again.", "Nimmt die herausgenommene Zelle an x, y, z wieder ins Raster auf, sodass der 3D-Löser sie wieder füllt."),
    ("setActiveTile", "Arms the tile the grid window's Pin utility places; only this window's state changes, not the document.", "Wählt die Kachel, die das Hilfsmittel Anheften im Rasterfenster setzt; nur der Zustand dieses Fensters ändert sich, nicht das Dokument."),
    ("pickCell", "Applies the grid window's armed utility to one cell given as x:y:z: Pin fixes the armed tile there, Mask carves the cell out, Select changes nothing.", "Wendet das gewählte Hilfsmittel des Rasterfensters auf eine als x:y:z angegebene Zelle an: Anheften setzt die gewählte Kachel, Ausblenden nimmt die Zelle heraus, Auswählen ändert nichts."),
    ("setActiveExample", "Replaces the whole document (grid, cell sizes, tiles, rules, pins, masks and seed) with one of the plugin's bundled 3D grid examples, by example id.", "Ersetzt das gesamte Dokument (Raster, Zellgrößen, Kacheln, Regeln, Anheftungen, Ausblendungen und Startwert) durch eines der mitgelieferten 3D-Raster-Beispiele, anhand der Beispiel-Id."),
    ("solve", "Starts the fill tool run that fills the 3D grid from its tiles, rules, pins and masks; the result is a preview in the grid window and does not change the document.", "Startet den Füll-Werkzeuglauf, der das 3D-Raster aus Kacheln, Regeln, Anheftungen und Ausblendungen füllt; das Ergebnis ist eine Vorschau im Rasterfenster und ändert das Dokument nicht."),
], [("worldSelect", "Input"), ("setCamera", "Chrome")])

for artifact, fn, dim, dim_de, move_en, move_de, size_en, size_de in [
    ("◻️2d", "create_wfc2d_editor", "2D", "2D", "Moves a slot so its lower corner sits at the given x, y; its size and connections stay the same.", "Verschiebt einen Slot so, dass seine untere Ecke bei x, y liegt; Größe und Verbindungen bleiben erhalten.", "Sets a slot's width and height; the preview scales the assigned tile into this box, and a zero or negative size is refused.", "Legt Breite und Höhe eines Slots fest; die Vorschau skaliert die zugewiesene Kachel in dieses Feld, eine Größe von null oder weniger wird abgelehnt."),
    ("🧊️3d", "create_wfc3d_editor", "3D", "3D", "Moves a slot so its lower corner sits at the given x, y and optional z; its size and connections stay the same.", "Verschiebt einen Slot so, dass seine untere Ecke bei x, y und optional z liegt; Größe und Verbindungen bleiben erhalten.", "Sets a slot's width, height and optional depth; the preview scales the assigned tile into this box, and a zero or negative size is refused.", "Legt Breite, Höhe und optional Tiefe eines Slots fest; die Vorschau skaliert die zugewiesene Kachel in dieses Feld, eine Größe von null oder weniger wird abgelehnt."),
]:
    describe(f"{A}/{artifact}/🏅️standards/🔖️1/🪆️subsets/✳️any/✏️editor/🦀️.rs", fn, [
        ("change-seed", "Sets the random seed the solve starts from; the same seed, slots and rules always produce the same assignment.", "Legt den Zufallsstartwert des Lösers fest; derselbe Startwert mit denselben Slots und Regeln ergibt immer dieselbe Belegung."),
        ("solve", f"Starts the fill tool run that assigns a tile to every slot of the {dim} slot graph along its adjacency edges; the result is a preview and does not change the document.", f"Startet den Füll-Werkzeuglauf, der jedem Slot des {dim_de}-Slotgraphen entlang seiner Nachbarschaftskanten eine Kachel zuweist; das Ergebnis ist eine Vorschau und ändert das Dokument nicht."),
        ("commit-fill", "Receives the result of a finished fill run for the preview window; nothing is written to the document.", "Nimmt das Ergebnis eines fertigen Füll-Laufs für das Vorschaufenster entgegen; ins Dokument wird nichts geschrieben."),
        ("create-slot", f"Adds a new slot, a {dim} box the solve assigns one tile to, with the given id, position and size; refused when the id is taken.", f"Fügt einen neuen Slot hinzu, ein {dim_de}-Feld, dem der Löser eine Kachel zuweist, mit der angegebenen Id, Position und Größe; eine vergebene Id wird abgelehnt."),
        ("delete-slot", "Removes a slot by id together with every adjacency edge connected to it.", "Entfernt einen Slot anhand seiner Id samt aller mit ihm verbundenen Nachbarschaftskanten."),
        ("move-slot", move_en, move_de),
        ("resize-slot", size_en, size_de),
        ("connect-slots", "Adds an adjacency edge with the given id and relation between two slots, so the solve must pick tiles the rules allow side by side there.", "Fügt zwischen zwei Slots eine Nachbarschaftskante mit der angegebenen Id und Relation hinzu, sodass der Löser dort nur laut Regeln verträgliche Kacheln wählt."),
        ("disconnect-slots", "Removes one adjacency edge by id, so its two slots no longer constrain each other.", "Entfernt eine Nachbarschaftskante anhand ihrer Id, sodass sich ihre beiden Slots nicht mehr gegenseitig einschränken."),
        ("pin-slot", "Fixes one slot to the given tile, or to the armed tile when none is given; the solve must keep it.", "Legt einen Slot auf die angegebene Kachel fest, ohne Angabe auf die gewählte Kachel; der Löser muss sie beibehalten."),
        ("unpin-slot", "Releases the tile pin of one slot so the solve may choose any tile for it again.", "Löst die Kachelanheftung eines Slots, sodass der Löser wieder jede Kachel dafür wählen darf."),
        ("setActiveExample", f"Replaces the whole document (slots, edges, tiles, rules and seed) with one of the plugin's bundled {dim} slot-graph examples, by example id.", f"Ersetzt das gesamte Dokument (Slots, Kanten, Kacheln, Regeln und Startwert) durch eines der mitgelieferten {dim_de}-Slotgraph-Beispiele, anhand der Beispiel-Id."),
        ("create-tile", "Adds a new placeable tile with the given id, label and weight to the tile catalogue; refused when the id is taken.", "Fügt dem Kachelkatalog eine neue setzbare Kachel mit der angegebenen Id, Bezeichnung und Gewichtung hinzu; eine vergebene Id wird abgelehnt."),
        ("delete-tile", "Removes a tile from the catalogue together with every rule that names it and every slot pinned to it.", "Entfernt eine Kachel aus dem Katalog samt aller Regeln, die sie nennen, und aller Slots, die auf sie angeheftet sind."),
        ("change-tile-weight", "Sets how strongly the solve favours one tile when several fit a slot; a higher weight makes it more frequent.", "Legt fest, wie stark der Löser eine Kachel bevorzugt, wenn mehrere in einen Slot passen; ein höheres Gewicht macht sie häufiger."),
        ("change-tile-media", "Clears the look of one tile back to the plain default box; its id, weight and rules stay unchanged.", "Setzt das Aussehen einer Kachel auf den schlichten Standardkörper zurück; Id, Gewicht und Regeln bleiben unverändert."),
        ("create-rule", "Allows or forbids tile B next to tile A under a named relation; along each edge the solve only places tile pairs the rules allow.", "Erlaubt oder verbietet Kachel B neben Kachel A unter einer benannten Relation; entlang jeder Kante setzt der Löser nur erlaubte Kachelpaare."),
        ("delete-rule", "Removes one adjacency rule by id, withdrawing the permission or ban it stated.", "Entfernt eine Nachbarschaftsregel anhand ihrer Id und nimmt die Erlaubnis oder das Verbot zurück, das sie ausdrückte."),
        ("change-active-tile", "Arms the tile that a pin gesture in this window assigns; only the editor's view state changes, not the document.", "Wählt die Kachel, die eine Anheften-Geste in diesem Fenster zuweist; nur der Ansichtszustand des Editors ändert sich, nicht das Dokument."),
    ], [("change-camera", "Chrome"), ("nodeGraphEdit", "Input")])
